  diag_mdns_fix: ["Aucune annonce reçue. Vérifie que l'Apple TV est allumée et sur le même réseau ; avec Docker, utilise network_mode: host.", "No announcement received. Check the Apple TV is on and on the same network; with Docker, use network_mode: host."],
  diag_apple: ["Serveurs Apple", "Apple servers"],
  diag_apple_fix: ["Apple est injoignable : vérifie la connexion Internet, le DNS ou un éventuel bloqueur.", "Apple can't be reached: check the Internet connection, DNS or any blocker."],
  diag_anisette: ["Serveur anisette", "Anisette server"],
  diag_anisette_fix: ["Le serveur anisette ne répond pas, ou ne fournit pas de données Windows (les seules qu'Apple accepte) : réessaie plus tard. Dans Réglages, laisse le serveur anisette vide (ani.jkcoxson.com, repli automatique sur ani2.stikstore.app) ; un serveur personnalisé doit fournir des données Windows, et tu peux en lister plusieurs : le suivant prend le relais.",
    "The anisette server isn't responding, or doesn't provide Windows data (the only kind Apple accepts): try later. In Settings, leave the anisette server empty (ani.jkcoxson.com, automatic fallback to ani2.stikstore.app); a custom server must provide Windows data, and you can list several: the next one takes over."],
  diag_github: ["GitHub (téléchargement des apps)", "GitHub (app downloads)"],
  diag_github_fix: ["GitHub est injoignable : les nouvelles versions ne seront pas téléchargées.", "GitHub can't be reached: new versions won't be downloaded."],
  diag_clock: ["Horloge", "Clock"],
  diag_clock_fix: ["L'heure de cette machine est décalée : active la synchronisation automatique (NTP), sinon la connexion Apple échoue.", "This machine's clock is off: turn on automatic time sync (NTP), or Apple sign-in fails."],
  diag_disk: ["Espace disque", "Disk space"],
  diag_disk_fix: ["Peu d'espace libre : chaque app occupe environ deux fois la taille de son IPA.", "Little free space: each app takes about twice the size of its IPA."],
  diag_event_loop: ["Moteur de tâches", "Task engine"],
  diag_event_loop_fix: ["Lance tvsign avec « python -m app » (pas uvicorn --reload).", "Start tvsign with “python -m app” (not uvicorn --reload)."],
  diag_footer: ["tvsign {v} · Python {py} · données : {dir} · {s} s", "tvsign {v} · Python {py} · data: {dir} · {s} s"],
  diag_d_plumesign_missing: ["introuvable : {path}", "not found: {path}"],
  diag_d_plumesign_no_answer: ["ne répond pas à --version", "does not answer --version"],
  diag_d_mdns: ["{total} annonce(s), {ours} appairée(s) avec tvsign, {pairable} en attente d'appairage", "{total} announcement(s), {ours} paired with tvsign, {pairable} waiting to be paired"],
  diag_d_disk: ["{gb} Go libres dans {dir}", "{gb} GB free in {dir}"],
  diag_d_loop: ["{name} : sous-processus impossibles, lance tvsign avec « python -m app »", "{name}: subprocesses impossible, start tvsign with “python -m app”"],
  diag_d_clock_none: ["aucune date serveur disponible pour comparer", "no server date available to compare"],
  diag_d_clock: ["écart de {s} s avec l'heure d'Apple", "{s} s off Apple's time"],

