  retry_at_n: ["Nouvel essai automatique {when} (échec n° {n} d'affilée, délai croissant).", "Automatic retry {when} (failure no. {n} in a row, increasing delay)."],
  version_pending: ["{from} installée · {to} en attente", "{from} installed · {to} pending"],
  version_pending_t: ["La nouvelle version n'est pas encore installée sur l'Apple TV.", "The new version is not installed on the Apple TV yet."],
  slots_line: ["Apps actives : {apps}/{max} sur « {tv} »", "Active apps: {apps}/{max} on “{tv}”"],
  slots_note: ["Les apps installées avec d'autres outils comptent aussi dans la limite d'Apple.", "Apps installed with other tools also count towards Apple's limit."],
  warn_slots_full: [" Ce compte a déjà {max} apps actives sur cette Apple TV : la limite du compte gratuit sera sans doute atteinte. Mets une autre app en pause ou utilise un autre compte.", " This account already has {max} active apps on this Apple TV: the free account limit will probably be reached. Pause another app or use another account."],
  tr_reconnect: ["reconnexion", "reconnected"],
  tr_paired: ["appairage", "paired"],
  journal_repeat: ["{n} fois, depuis {when}", "{n} times, since {when}"],
  loop_restarted: ["relancée {n} fois", "restarted {n} times"],
  renew_window_from: ["Renouveler seulement de", "Renew only from"],
  renew_window_to: ["jusqu'à", "until"],
  renew_window_note: ["Les renouvellements non urgents n'ont lieu que dans cette plage (heure locale ; vide : à toute heure). Ignorée quand il reste moins de 24 h, et pour un renouvellement lancé à la main. Début = fin : toute la journée.", "Non-urgent renewals only happen within this range (local time; empty: any time). Ignored when less than 24 h remain, and for a manual renewal. Start = end: all day."],
  diag_password_file: ["Mot de passe prédéfini", "Preset password"],
  diag_password_file_fix: ["TVSIGN_PASSWORD_FILE est défini mais inutilisable : le mot de passe prévu n'est PAS appliqué. Rends le fichier lisible par l'utilisateur de tvsign (PUID/PGID) ou corrige le chemin, puis redémarre.", "TVSIGN_PASSWORD_FILE is set but unusable: the intended password is NOT applied. Make the file readable by the tvsign user (PUID/PGID) or fix the path, then restart."],
  err_busy: ["Un renouvellement, une connexion Apple ou un appairage est en cours : réessaie dans un instant.", "A renewal, Apple sign-in or pairing is in progress: try again in a moment."],
  err_plumesign_busy: ["L'outil de signature est occupé (connexion Apple en attente d'un code ?). Réessaie dans un instant.", "The signing tool is busy (Apple sign-in waiting for a code?). Try again in a moment."],
  err_url_expected: ["Adresse http(s):// attendue.", "An http(s):// address is expected."],
  err_range: ["Valeur attendue entre {n} et {m}.", "A value between {n} and {m} is expected."],
  err_language_expected: ["Langue : auto, en ou fr.", "Language: auto, en or fr."],
  err_onoff_expected: ["Choix attendu : on ou off.", "One of on or off is expected."],
  err_hour_expected: ["Heure attendue, de 0 à 23.", "An hour from 0 to 23 is expected."],
  err_window_incomplete: ["Indique l'heure de début et de fin, ou laisse les deux vides.", "Enter both a start and an end hour, or leave both empty."],
  err_set_by_env: ["Défini par {n}.", "Set by {n}."],
  err_credentials_required: ["Indique l'identifiant Apple et le mot de passe.", "Enter the Apple ID and password."],
  st_window: ["En attente de la plage horaire (dès {h} h)", "Waiting for the time window (from {h} h)"],
  retry_window: ["Nouvel essai automatique dans la plage horaire choisie, {when}.", "Automatic retry within the chosen time window, {when}."],
