let LANG = "en";
const langueNavigateur = () => ((navigator.languages && navigator.languages[0]) || navigator.language || "en").toLowerCase().startsWith("fr") ? "fr" : "en";
const setLang = (l) => { LANG = l === "fr" ? "fr" : "en"; };
const LOCALE = () => (LANG === "fr" ? "fr-FR" : "en-GB");

function t(key, vars) {
  const entry = I18N[key];
  if (!entry) return key;
  let s = entry[LANG === "fr" ? 0 : 1] ?? entry[1];
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
  return s;
}
function tn(key, n, vars = {}) {
  return t(key + (n === 1 ? "_one" : "_other"), { n, ...vars });
}
